examples.source:
grammar Hello {
  @ubnf: v2
  @package: guide.demo

  @root
  @mapping(Greeting, params=[text])
  @doc('hello と入力してください。大文字小文字を区別します。')
  Start ::= 'hello' @text;
}

grammar Numbers {
  @ubnf: v2
  @package: guide.demo

  token DIGIT ::= CHAR_RANGE('0', '9');
  token NUMBER ::= [ '+' | '-' ] DIGIT+ [ '.' DIGIT+ ];

  @root
  @mapping(NumberText, params=[text])
  @doc('整数または小数。符号は省略可能。指数表記は使いません。')
  Start ::= NUMBER @text;
}

grammar Assignments {
  @ubnf: v2
  @package: guide.demo
  @whitespace: javaStyle

  token DIGIT ::= CHAR_RANGE('0', '9');
  token LETTER ::= CHAR_RANGE('a', 'z') | CHAR_RANGE('A', 'Z') | '_';
  token IDENTIFIER ::= LETTER (LETTER | DIGIT)*;
  token NUMBER ::= [ '+' | '-' ] DIGIT+ [ '.' DIGIT+ ];

  @root
  @mapping(Assignment, params=[name, value])
  @doc('price = 12; のように、名前と数を = で結んで ; で終えます。')
  Start ::= IDENTIFIER @name '=' NUMBER @value ';';
}

grammar Lists {
  @ubnf: v2
  @package: guide.demo
  @whitespace: javaStyle

  token NUMBER ::= CHAR_RANGE('0', '9')+;

  @root
  @mapping(NumberList, params=[values])
  @doc('[] または [1,2,30] のような整数のリストです。末尾カンマは使いません。')
  Start ::= '[' [ NUMBER @values { ',' NUMBER @values } ] ']';
}

grammar Strings {
  @ubnf: v2
  @package: guide.demo

  token STRING ::= '"' { '\\' ANY | NEGATION('"\\\n\r') } '"';

  @root
  @mapping(Quoted, params=[text])
  @doc('二重引用符で囲みます。バックスラッシュで直後の文字をエスケープできます。')
  Start ::= STRING @text;
}

grammar Fences {
  @ubnf: v2
  @package: guide.demo

  token FENCE ::= CAPTURE(mark, '~'+)
    { NEGATIVE_LOOKAHEAD(SAME_AS(mark)) ANY } SAME_AS(mark);

  @root
  @mapping(Fenced, params=[text])
  @doc('~~~hello~~~ のように同じ個数の ~ で囲みます。最初の同じ区切りで閉じます。')
  Start ::= FENCE @text;
}
